/**
 * Event Bus - In-memory publish/subscribe system
 * Enables decoupled inter-service communication
 */

type EventCallback = (payload: any) => void;

export class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  /**
   * Publish an event to all subscribers
   */
  publish(event: string, payload: any): void {
    const callbacks = this.subscribers.get(event) || [];
    callbacks.forEach((callback) => {
      try {
        callback(payload);
      } catch (error) {
        console.error(`Error in event handler for "${event}":`, error);
      }
    });
  }

  /**
   * Subscribe to an event
   */
  subscribe(event: string, callback: EventCallback): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event)!.push(callback);
  }
}

/**
 * User Service - Manages user data
 * Data ownership: User records (id, name, email)
 * No events published or subscribed
 */

export interface User {
  id: string;
  name: string;
  email: string;
}

export class UserService {
  private users: Map<string, User> = new Map();
  private nextId = 1;

  /**
   * Create a new user
   */
  create(name: string, email: string): User {
    const id = `user_${this.nextId++}`;
    const user: User = { id, name, email };
    this.users.set(id, user);
    return user;
  }

  /**
   * Get user by ID
   */
  getById(id: string): User | null {
    return this.users.get(id) || null;
  }

  /**
   * Get all users
   */
  getAll(): User[] {
    return Array.from(this.users.values());
  }

  /**
   * Update user
   */
  update(id: string, updates: Partial<User>): User | null {
    const user = this.users.get(id);
    if (!user) return null;

    const updated = { ...user, ...updates, id };
    this.users.set(id, updated);
    return updated;
  }

  /**
   * Delete user
   */
  delete(id: string): boolean {
    return this.users.delete(id);
  }
}

/**
 * Project Service - Manages projects and their members
 * Data ownership: Project records (id, name, description, memberIds)
 * No events published or subscribed
 */

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export class ProjectService {
  private projects: Map<string, Project> = new Map();
  private nextId = 1;

  /**
   * Create a new project
   */
  create(name: string, description: string): Project {
    const id = `proj_${this.nextId++}`;
    const project: Project = {
      id,
      name,
      description,
      memberIds: [],
    };
    this.projects.set(id, project);
    return project;
  }

  /**
   * Get project by ID
   */
  getById(id: string): Project | null {
    return this.projects.get(id) || null;
  }

  /**
   * Get all projects
   */
  getAll(): Project[] {
    return Array.from(this.projects.values());
  }

  /**
   * Update project
   */
  update(id: string, updates: Partial<Project>): Project | null {
    const project = this.projects.get(id);
    if (!project) return null;

    // Don't allow updating memberIds directly; use addMember/removeMember
    const updated = {
      ...project,
      name: updates.name ?? project.name,
      description: updates.description ?? project.description,
    };
    this.projects.set(id, updated);
    return updated;
  }

  /**
   * Delete project
   */
  delete(id: string): boolean {
    return this.projects.delete(id);
  }

  /**
   * Add a member to the project
   */
  addMember(projectId: string, userId: string): Project | null {
    const project = this.projects.get(projectId);
    if (!project) return null;

    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
    }
    return project;
  }

  /**
   * Remove a member from the project
   */
  removeMember(projectId: string, userId: string): Project | null {
    const project = this.projects.get(projectId);
    if (!project) return null;

    project.memberIds = project.memberIds.filter((id) => id !== userId);
    return project;
  }
}

/**
 * Task Service - Manages tasks and their status/assignments
 * Data ownership: Task records (id, title, description, status, assigneeId, projectId)
 * Events published:
 *   - task.assigned: {taskId, taskTitle, assigneeId}
 *   - task.statusChanged: {taskId, taskTitle, assigneeId, oldStatus, newStatus}
 */

import { EventBus } from "../event-bus.js";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: "todo" | "in-progress" | "done";
  assigneeId: string | null;
  projectId: string;
}

export class TaskService {
  private tasks: Map<string, Task> = new Map();
  private nextId = 1;

  constructor(private eventBus: EventBus) {}

  /**
   * Create a new task
   */
  create(
    title: string,
    description: string,
    projectId: string
  ): Task {
    const id = `task_${this.nextId++}`;
    const task: Task = {
      id,
      title,
      description,
      status: "todo",
      assigneeId: null,
      projectId,
    };
    this.tasks.set(id, task);
    return task;
  }

  /**
   * Get task by ID
   */
  getById(id: string): Task | null {
    return this.tasks.get(id) || null;
  }

  /**
   * Get all tasks
   */
  getAll(): Task[] {
    return Array.from(this.tasks.values());
  }

  /**
   * Get tasks by project ID
   */
  getByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (task) => task.projectId === projectId
    );
  }

  /**
   * Update task (basic fields only)
   */
  update(id: string, updates: Partial<Task>): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    const updated = {
      ...task,
      title: updates.title ?? task.title,
      description: updates.description ?? task.description,
    };
    this.tasks.set(id, updated);
    return updated;
  }

  /**
   * Delete task
   */
  delete(id: string): boolean {
    return this.tasks.delete(id);
  }

  /**
   * Assign task to a user
   */
  assign(taskId: string, assigneeId: string): Task | null {
    const task = this.tasks.get(taskId);
    if (!task) return null;

    task.assigneeId = assigneeId;
    this.tasks.set(taskId, task);

    // Publish event
    this.eventBus.publish("task.assigned", {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId,
    });

    return task;
  }

  /**
   * Change task status (forward-only: todo → in-progress → done)
   */
  changeStatus(
    taskId: string,
    newStatus: "todo" | "in-progress" | "done"
  ): Task | null {
    const task = this.tasks.get(taskId);
    if (!task) return null;

    // Validate forward-only transitions
    const statusOrder = { todo: 0, "in-progress": 1, done: 2 };
    const currentOrder = statusOrder[task.status];
    const newOrder = statusOrder[newStatus];

    if (newOrder < currentOrder) {
      throw new Error(
        `Invalid status transition: ${task.status} -> ${newStatus}`
      );
    }

    const oldStatus = task.status;
    task.status = newStatus;
    this.tasks.set(taskId, task);

    // Publish event
    if (task.assigneeId) {
      this.eventBus.publish("task.statusChanged", {
        taskId: task.id,
        taskTitle: task.title,
        assigneeId: task.assigneeId,
        oldStatus,
        newStatus,
      });
    }

    return task;
  }
}

/**
 * Comment Service - Manages task comments
 * Data ownership: Comment records (id, taskId, authorId, body, createdAt)
 * Events published:
 *   - comment.added: {commentId, taskId, taskTitle, authorId, authorName}
 */

import { EventBus } from "../event-bus.js";

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: number;
}

export class CommentService {
  private comments: Map<string, Comment> = new Map();
  private nextId = 1;

  constructor(private eventBus: EventBus) {}

  /**
   * Create a new comment
   */
  create(
    taskId: string,
    authorId: string,
    authorName: string,
    body: string,
    taskTitle: string
  ): Comment {
    const id = `comment_${this.nextId++}`;
    const comment: Comment = {
      id,
      taskId,
      authorId,
      body,
      createdAt: Date.now(),
    };
    this.comments.set(id, comment);

    // Publish event
    this.eventBus.publish("comment.added", {
      commentId: id,
      taskId,
      taskTitle,
      authorId,
      authorName,
    });

    return comment;
  }

  /**
   * Get comment by ID
   */
  getById(id: string): Comment | null {
    return this.comments.get(id) || null;
  }

  /**
   * Get all comments for a task
   */
  getByTask(taskId: string): Comment[] {
    return Array.from(this.comments.values()).filter(
      (comment) => comment.taskId === taskId
    );
  }

  /**
   * Delete comment
   */
  delete(id: string): boolean {
    return this.comments.delete(id);
  }
}

/**
 * Notification Service - Manages user notifications
 * Data ownership: Notification records (id, userId, message, read, createdAt)
 * Events subscribed:
 *   - task.assigned: creates notification for assignee
 *   - task.statusChanged: creates notification for assignee
 *   - comment.added: creates notification for task assignee
 */

import { EventBus } from "../event-bus.js";

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: number;
}

export class NotificationService {
  private notifications: Map<string, Notification> = new Map();
  private nextId = 1;

  constructor(eventBus: EventBus) {
    // Subscribe to task.assigned event
    eventBus.subscribe("task.assigned", (payload) => {
      this.createNotification(
        payload.assigneeId,
        `Task "${payload.taskTitle}" has been assigned to you`
      );
    });

    // Subscribe to task.statusChanged event
    eventBus.subscribe("task.statusChanged", (payload) => {
      this.createNotification(
        payload.assigneeId,
        `Task "${payload.taskTitle}" status changed from "${payload.oldStatus}" to "${payload.newStatus}"`
      );
    });

    // Subscribe to comment.added event
    eventBus.subscribe("comment.added", (payload) => {
      this.createNotification(
        payload.assigneeId,
        `${payload.authorName} commented on task "${payload.taskTitle}"`
      );
    });
  }

  /**
   * Internal method to create a notification
   */
  private createNotification(userId: string, message: string): Notification {
    const id = `notif_${this.nextId++}`;
    const notification: Notification = {
      id,
      userId,
      message,
      read: false,
      createdAt: Date.now(),
    };
    this.notifications.set(id, notification);
    return notification;
  }

  /**
   * Get notifications for a user
   */
  getByUser(userId: string): Notification[] {
    return Array.from(this.notifications.values())
      .filter((notif) => notif.userId === userId)
      .sort((a, b) => b.createdAt - a.createdAt);
  }

  /**
   * Mark notification as read
   */
  markAsRead(notificationId: string): Notification | null {
    const notification = this.notifications.get(notificationId);
    if (!notification) return null;

    notification.read = true;
    this.notifications.set(notificationId, notification);
    return notification;
  }
}

/**
 * API Router - HTTP request handler using Node.js built-in http module
 * Routes all requests to appropriate services
 */

import { IncomingMessage, ServerResponse } from "http";
import { URL } from "url";
import { UserService } from "./services/user-service.js";
import { ProjectService } from "./services/project-service.js";
import { TaskService } from "./services/task-service.js";
import { CommentService } from "./services/comment-service.js";
import { NotificationService } from "./services/notification-service.js";

export class Router {
  constructor(
    private userService: UserService,
    private projectService: ProjectService,
    private taskService: TaskService,
    private commentService: CommentService,
    private notificationService: NotificationService
  ) {}

  /**
   * Main request handler
   */
  async handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const url = new URL(req.url || "/", `http://${req.headers.host}`);
    const pathname = url.pathname;
    const method = req.method || "GET";

    try {
      // Parse body for POST/PUT requests
      let body: any = {};
      if (method === "POST" || method === "PUT") {
        body = await this.parseBody(req);
      }

      // Route requests
      if (pathname === "/users" && method === "GET") {
        return this.sendJson(res, 200, this.userService.getAll());
      }

      if (pathname === "/users" && method === "POST") {
        const user = this.userService.create(body.name, body.email);
        return this.sendJson(res, 201, user);
      }

      const userIdMatch = pathname.match(/^\/users\/([^/]+)$/);
      if (userIdMatch && method === "GET") {
        const user = this.userService.getById(userIdMatch[1]);
        if (!user) return this.sendJson(res, 404, { error: "User not found" });
        return this.sendJson(res, 200, user);
      }

      if (userIdMatch && method === "PUT") {
        const user = this.userService.update(userIdMatch[1], body);
        if (!user) return this.sendJson(res, 404, { error: "User not found" });
        return this.sendJson(res, 200, user);
      }

      if (userIdMatch && method === "DELETE") {
        const deleted = this.userService.delete(userIdMatch[1]);
        if (!deleted) return this.sendJson(res, 404, { error: "User not found" });
        return this.sendJson(res, 204, null);
      }

      // Projects routes
      if (pathname === "/projects" && method === "GET") {
        return this.sendJson(res, 200, this.projectService.getAll());
      }

      if (pathname === "/projects" && method === "POST") {
        const project = this.projectService.create(body.name, body.description);
        return this.sendJson(res, 201, project);
      }

      const projectIdMatch = pathname.match(/^\/projects\/([^/]+)$/);
      if (projectIdMatch && method === "GET") {
        const project = this.projectService.getById(projectIdMatch[1]);
        if (!project)
          return this.sendJson(res, 404, { error: "Project not found" });
        return this.sendJson(res, 200, project);
      }

      if (projectIdMatch && method === "PUT") {
        const project = this.projectService.update(projectIdMatch[1], body);
        if (!project)
          return this.sendJson(res, 404, { error: "Project not found" });
        return this.sendJson(res, 200, project);
      }

      if (projectIdMatch && method === "DELETE") {
        const deleted = this.projectService.delete(projectIdMatch[1]);
        if (!deleted)
          return this.sendJson(res, 404, { error: "Project not found" });
        return this.sendJson(res, 204, null);
      }

      // Project members routes
      const projectMembersMatch = pathname.match(/^\/projects\/([^/]+)\/members$/);
      if (projectMembersMatch && method === "POST") {
        const project = this.projectService.addMember(
          projectMembersMatch[1],
          body.userId
        );
        if (!project)
          return this.sendJson(res, 404, { error: "Project not found" });
        return this.sendJson(res, 200, project);
      }

      if (projectMembersMatch && method === "DELETE") {
        const project = this.projectService.removeMember(
          projectMembersMatch[1],
          body.userId
        );
        if (!project)
          return this.sendJson(res, 404, { error: "Project not found" });
        return this.sendJson(res, 200, project);
      }

      // Tasks routes
      if (pathname === "/tasks" && method === "GET") {
        const projectId = url.searchParams.get("projectId");
        if (projectId) {
          return this.sendJson(res, 200, this.taskService.getByProject(projectId));
        }
        return this.sendJson(res, 200, this.taskService.getAll());
      }

      if (pathname === "/tasks" && method === "POST") {
        const task = this.taskService.create(
          body.title,
          body.description,
          body.projectId
        );
        return this.sendJson(res, 201, task);
      }

      const taskIdMatch = pathname.match(/^\/tasks\/([^/]+)$/);
      if (taskIdMatch && method === "GET") {
        const task = this.taskService.getById(taskIdMatch[1]);
        if (!task) return this.sendJson(res, 404, { error: "Task not found" });
        return this.sendJson(res, 200, task);
      }

      if (taskIdMatch && method === "PUT") {
        const task = this.taskService.update(taskIdMatch[1], body);
        if (!task) return this.sendJson(res, 404, { error: "Task not found" });
        return this.sendJson(res, 200, task);
      }

      if (taskIdMatch && method === "DELETE") {
        const deleted = this.taskService.delete(taskIdMatch[1]);
        if (!deleted) return this.sendJson(res, 404, { error: "Task not found" });
        return this.sendJson(res, 204, null);
      }

      // Task status change
      const taskStatusMatch = pathname.match(/^\/tasks\/([^/]+)\/status$/);
      if (taskStatusMatch && method === "PUT") {
        const task = this.taskService.changeStatus(taskStatusMatch[1], body.status);
        if (!task) return this.sendJson(res, 404, { error: "Task not found" });
        return this.sendJson(res, 200, task);
      }

      // Task assignment
      const taskAssignMatch = pathname.match(/^\/tasks\/([^/]+)\/assign$/);
      if (taskAssignMatch && method === "PUT") {
        const task = this.taskService.assign(taskAssignMatch[1], body.assigneeId);
        if (!task) return this.sendJson(res, 404, { error: "Task not found" });
        return this.sendJson(res, 200, task);
      }

      // Comments routes
      if (pathname === "/comments" && method === "GET") {
        const taskId = url.searchParams.get("taskId");
        if (taskId) {
          return this.sendJson(res, 200, this.commentService.getByTask(taskId));
        }
        return this.sendJson(res, 400, { error: "taskId parameter required" });
      }

      if (pathname === "/comments" && method === "POST") {
        const comment = this.commentService.create(
          body.taskId,
          body.authorId,
          body.authorName,
          body.body,
          body.taskTitle
        );
        return this.sendJson(res, 201, comment);
      }

      const commentIdMatch = pathname.match(/^\/comments\/([^/]+)$/);
      if (commentIdMatch && method === "GET") {
        const comment = this.commentService.getById(commentIdMatch[1]);
        if (!comment)
          return this.sendJson(res, 404, { error: "Comment not found" });
        return this.sendJson(res, 200, comment);
      }

      if (commentIdMatch && method === "DELETE") {
        const deleted = this.commentService.delete(commentIdMatch[1]);
        if (!deleted)
          return this.sendJson(res, 404, { error: "Comment not found" });
        return this.sendJson(res, 204, null);
      }

      // Notifications routes
      if (pathname === "/notifications" && method === "GET") {
        const userId = url.searchParams.get("userId");
        if (!userId) {
          return this.sendJson(res, 400, { error: "userId parameter required" });
        }
        return this.sendJson(res, 200, this.notificationService.getByUser(userId));
      }

      const notifReadMatch = pathname.match(/^\/notifications\/([^/]+)\/read$/);
      if (notifReadMatch && method === "PUT") {
        const notif = this.notificationService.markAsRead(notifReadMatch[1]);
        if (!notif)
          return this.sendJson(res, 404, { error: "Notification not found" });
        return this.sendJson(res, 200, notif);
      }

      // 404 Not Found
      return this.sendJson(res, 404, { error: "Route not found" });
    } catch (error) {
      console.error("Router error:", error);
      return this.sendJson(res, 500, {
        error: error instanceof Error ? error.message : "Internal server error",
      });
    }
  }

  /**
   * Parse JSON body from request
   */
  private parseBody(req: IncomingMessage): Promise<any> {
    return new Promise((resolve, reject) => {
      let data = "";

      req.on("data", (chunk) => {
        data += chunk.toString();
      });

      req.on("end", () => {
        try {
          resolve(data ? JSON.parse(data) : {});
        } catch (error) {
          reject(new Error("Invalid JSON in request body"));
        }
      });

      req.on("error", reject);
    });
  }

  /**
   * Send JSON response
   */
  private sendJson(
    res: ServerResponse,
    statusCode: number,
    data: any
  ): void {
    res.writeHead(statusCode, { "Content-Type": "application/json" });
    if (statusCode === 204) {
      res.end();
    } else {
      res.end(JSON.stringify(data, null, 2));
    }
  }
}

/**
 * Main Entry Point - Wires up all services and starts the HTTP server
 */

import { createServer } from "http";
import { EventBus } from "./event-bus.js";
import { UserService } from "./services/user-service.js";
import { ProjectService } from "./services/project-service.js";
import { TaskService } from "./services/task-service.js";
import { CommentService } from "./services/comment-service.js";
import { NotificationService } from "./services/notification-service.js";
import { Router } from "./router.js";

const PORT = process.env.PORT ? parseInt(process.env.PORT) : 3000;

/**
 * Start the application
 */
async function start() {
  // Create event bus
  const eventBus = new EventBus();

  // Create services
  const userService = new UserService();
  const projectService = new ProjectService();
  const taskService = new TaskService(eventBus);
  const commentService = new CommentService(eventBus);
  const notificationService = new NotificationService(eventBus);

  // Create router
  const router = new Router(
    userService,
    projectService,
    taskService,
    commentService,
    notificationService
  );

  // Create HTTP server
  const server = createServer((req, res) => {
    router.handle(req, res).catch((error) => {
      console.error("Unhandled error:", error);
      res.writeHead(500, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: "Internal server error" }));
    });
  });

  // Start listening
  server.listen(PORT, () => {
    console.log(`Task Management API server running on http://localhost:${PORT}`);
  });

  return server;
}

// Start the server
start().catch((error) => {
  console.error("Failed to start server:", error);
  process.exit(1);
});

export { start };

/**
 * Demo Script - Exercises all features of the Task Management API
 * Runs through: create users → create project → add members → create tasks →
 * assign tasks → change status → add comments → check notifications
 */

import { start } from "./main.js";
import { Server } from "http";

const BASE_URL = "http://localhost:3000";

/**
 * Make HTTP request helper
 */
async function request(
  method: string,
  path: string,
  body?: any
): Promise<any> {
  return new Promise((resolve, reject) => {
    const url = new URL(path, BASE_URL);
    const options = {
      hostname: url.hostname,
      port: url.port || 3000,
      path: url.pathname + url.search,
      method,
      headers: {
        "Content-Type": "application/json",
      },
    };

    const req = require("http").request(options, (res: any) => {
      let data = "";

      res.on("data", (chunk: any) => {
        data += chunk;
      });

      res.on("end", () => {
        try {
          const result = data ? JSON.parse(data) : null;
          resolve({ status: res.statusCode, body: result });
        } catch (error) {
          resolve({ status: res.statusCode, body: data });
        }
      });
    });

    req.on("error", reject);

    if (body) {
      req.write(JSON.stringify(body));
    }

    req.end();
  });
}

